// src/auth/device-auth.ts
import { eq, and } from "drizzle-orm";
async function requireDeviceAuth(request, reply) {
  const authHeader = request.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    reply.status(401).send({
      statusCode: 401,
      error: "Unauthorized",
      message: "Missing or invalid Authorization header"
    });
    return;
  }
  const token = authHeader.slice(7).trim();
  let payload;
  try {
    payload = verifyDeviceToken(token);
  } catch {
    reply.status(401).send({
      statusCode: 401,
      error: "Unauthorized",
      message: "Invalid or expired token"
    });
    return;
  }
  const db = request.server.db || getDb();
  try {
    const matchingDevices = await db.select().from(devices).where(and(eq(devices.id, payload.deviceId), eq(devices.pharmacyId, payload.pharmacyId))).limit(1);
    const device = matchingDevices[0];
    if (!device) {
      reply.status(401).send({
        statusCode: 401,
        error: "Unauthorized",
        message: "Device not found or does not belong to specified tenant"
      });
      return;
    }
    if (device.isRevoked) {
      reply.status(403).send({
        statusCode: 403,
        error: "Forbidden",
        message: "Device has been revoked"
      });
      return;
    }
    request.deviceContext = {
      pharmacyId: device.pharmacyId,
      branchId: device.branchId || payload.branchId,
      deviceId: device.id,
      counterId: device.counterId,
      deviceName: device.deviceName
    };
    if (typeof db.update === "function") {
      const now = (/* @__PURE__ */ new Date()).toISOString();
      db.update(devices).set({ lastSeenAt: now, updatedAt: now }).where(eq(devices.id, device.id)).catch((err) => {
        request.log.error(err, "Failed to update device lastSeenAt");
      });
    }
  } catch (err) {
    request.log.error(err, "Failed to authenticate device");
    reply.status(500).send({
      statusCode: 500,
      error: "Internal Server Error",
      message: "Failed to verify device authorization"
    });
  }
}

// src/routes/devices.ts
var RegisterDeviceSchema = external_exports.object({
  code: external_exports.string().min(1, "Registration code is required"),
  deviceName: external_exports.string().min(1, "Device name is required"),
  deviceFingerprint: external_exports.string().optional()
});
var deviceRoutes = async (fastify, options) => {
  const registerMax = options.registerRateLimitMax ?? 5;
  const registerWindow = options.registerRateLimitWindow ?? "1 minute";
  fastify.post(
    "/register",
    {
      config: {
        rateLimit: {
          max: registerMax,
          timeWindow: registerWindow
        }
      }
    },
    async (request, reply) => {
      const parsed = RegisterDeviceSchema.safeParse(request.body);
      if (!parsed.success) {
        return reply.status(400).send({
          statusCode: 400,
          error: "Bad Request",
          message: parsed.error.issues[0]?.message || "Invalid registration input"
        });
      }
      const { code, deviceName, deviceFingerprint } = parsed.data;
      const db = request.server.db || getDb();
      const codeHash = hashRegistrationCode(code);
      const matchingCodes = await db.select().from(deviceRegistrationCodes).where(eq2(deviceRegistrationCodes.codeHash, codeHash)).limit(1);
      const codeRecord = matchingCodes[0];
      if (!codeRecord) {
        return reply.status(400).send({
          statusCode: 400,
          error: "Bad Request",
          message: "Invalid registration code"
        });
      }
      if (codeRecord.usedAt !== null) {
        return reply.status(400).send({
          statusCode: 400,
          error: "Bad Request",
          message: "Registration code has already been used"
        });
      }
      const expiresAt = new Date(codeRecord.expiresAt).getTime();
      if (Number.isNaN(expiresAt) || expiresAt < Date.now()) {
        return reply.status(400).send({
          statusCode: 400,
          error: "Bad Request",
          message: "Registration code has expired"
        });
      }
      const deviceId = generateUuidV7();
      const now = (/* @__PURE__ */ new Date()).toISOString();
      try {
        await db.transaction(async (tx) => {
          const updated = await tx.update(deviceRegistrationCodes).set({ usedAt: now }).where(
            and2(
              eq2(deviceRegistrationCodes.id, codeRecord.id),
              isNull(deviceRegistrationCodes.usedAt)
            )
          ).returning({ id: deviceRegistrationCodes.id });
          if (updated.length === 0) {
            throw new Error("CODE_ALREADY_USED");
          }
          await tx.insert(devices).values({
            id: deviceId,
            pharmacyId: codeRecord.pharmacyId,
            branchId: codeRecord.branchId,
            counterId: codeRecord.counterId,
            deviceName: deviceName.trim(),
            deviceFingerprint: deviceFingerprint ? deviceFingerprint.trim() : null,
            isRevoked: false,
            lastSeenAt: now,
            createdAt: now,
            updatedAt: now
          });
        });
      } catch (err) {
        if (err instanceof Error && err.message === "CODE_ALREADY_USED") {
          return reply.status(400).send({
            statusCode: 400,
            error: "Bad Request",
            message: "Registration code has already been used"
          });
        }
        request.log.error(err, "Failed to complete device registration");
        return reply.status(500).send({
          statusCode: 500,
          error: "Internal Server Error",
          message: "Failed to complete device registration"
        });
      }
      const token = signDeviceToken({
        pharmacyId: codeRecord.pharmacyId,
        branchId: codeRecord.branchId,
        deviceId
      });
      return reply.status(201).send({
        ok: true,
        deviceId,
        pharmacyId: codeRecord.pharmacyId,
        branchId: codeRecord.branchId,
        token
      });
    }
  );
  fastify.get(
    "/me",
    {
      preHandler: [requireDeviceAuth]
    },
    async (request) => {
      return {
        ok: true,
        deviceContext: request.deviceContext
      };
    }
  );
};

