async function applyStockTransferReceived(tx, ctx, rawPayload) {
  const parseResult = StockTransferReceivedPayloadSchema.safeParse(rawPayload);
  if (!parseResult.success) {
    throw new SyncRejectedError(
      "INVALID_PAYLOAD",
      `Invalid stock_transfer.received payload: ${parseResult.error.message}`
    );
  }
  const payload = parseResult.data;
  const now = (/* @__PURE__ */ new Date()).toISOString();
  const [transfer] = await tx.select().from(stockTransfers).where(
    and11(eq11(stockTransfers.id, payload.transferId), eq11(stockTransfers.pharmacyId, ctx.pharmacyId))
  );
  if (!transfer) {
    throw new SyncRetryLaterError(
      "TRANSFER_NOT_FOUND",
      `Transfer ${payload.transferId} not found yet; will retry on next sync cycle`
    );
  }
  if (transfer.status === "received") {
    return;
  }
  if (ctx.branchId && transfer.destinationBranchId !== ctx.branchId) {
    throw new SyncRejectedError(
      "CROSS_TENANT_REFERENCE",
      `Device branchId (${ctx.branchId}) does not match transfer destinationBranchId (${transfer.destinationBranchId})`
    );
  }
  if (payload.receivedByUserId) {
    await verifyTenantEntity(
      tx,
      users,
      payload.receivedByUserId,
      ctx.pharmacyId,
      "UNKNOWN_USER",
      "receivedByUser"
    );
  }
  const productIds = payload.lines.map((l) => l.productId);
  await verifyTenantEntities(
    tx,
    products,
    productIds,
    ctx.pharmacyId,
    "UNKNOWN_PRODUCT",
    "product"
  );
  const batchIds = payload.lines.map((l) => l.batchId);
  await verifyTenantEntities(tx, batches, batchIds, ctx.pharmacyId, "UNKNOWN_BATCH", "batch");
  let hasShortage = false;
  for (const line of payload.lines) {
    const receiveMovementId = line.receiveMovementId || line.lineId;
    const isShortage = line.shortageQuantity > 0;
    if (isShortage) {
      hasShortage = true;
    }
    const updatedLines = await tx.update(stockTransferLines).set({
      quantityReceived: line.quantityReceived,
      shortageQuantity: line.shortageQuantity,
      shortageReason: line.shortageReason || null,
      receiveMovementId,
      shortageMovementId: line.shortageMovementId || null,
      updatedAt: now
    }).where(
      and11(
        eq11(stockTransferLines.id, line.lineId),
        eq11(stockTransferLines.transferId, transfer.id),
        eq11(stockTransferLines.pharmacyId, ctx.pharmacyId)
      )
    ).returning({ id: stockTransferLines.id });
    if (updatedLines.length === 0) {
      throw new SyncRejectedError(
        "CROSS_TENANT_REFERENCE",
        `Transfer line ${line.lineId} does not belong to transfer ${transfer.id} or pharmacy ${ctx.pharmacyId}`
      );
    }
    if (line.quantityReceived > 0) {
      const [existingIn] = await tx.select().from(stockMovements).where(
        and11(
          eq11(stockMovements.id, receiveMovementId),
          eq11(stockMovements.pharmacyId, ctx.pharmacyId)
        )
      );
      if (!existingIn) {
        const moveData = {
          id: receiveMovementId,
          pharmacyId: ctx.pharmacyId,
          productId: line.productId,
          batchId: line.batchId,
          branchId: transfer.destinationBranchId,
          locationId: transfer.destinationLocationId || null,
          type: "transfer_in",
          quantitySigned: line.quantityReceived,
          referenceType: "stock_transfer",
          referenceId: transfer.id,
          reason: `Transfer In: ${transfer.transferNumber}`,
          createdAt: payload.receivedAt || now,
          updatedAt: payload.receivedAt || now
        };
        await tx.insert(stockMovements).values(moveData);
        await insertChangeLog(tx, {
          pharmacyId: ctx.pharmacyId,
          branchId: transfer.destinationBranchId,
          entity: "stock_movement",
          entityId: receiveMovementId,
          op: "upsert",
          data: moveData,
          createdAt: now
        });
      }
    }
  }
  await tx.update(stockTransfers).set({
    status: "received",
    receivedBy: payload.receivedByUserId || null,
    receivedAt: payload.receivedAt,
    hasShortage,
    updatedAt: now
  }).where(and11(eq11(stockTransfers.id, transfer.id), eq11(stockTransfers.pharmacyId, ctx.pharmacyId)));
  await postStockTransferReceived(tx, {
    pharmacyId: ctx.pharmacyId,
    sourceBranchId: transfer.sourceBranchId,
    destinationBranchId: transfer.destinationBranchId,
    transferId: transfer.id,
    transferNumber: transfer.transferNumber,
    createdBy: payload.receivedByUserId || null,
    lines: payload.lines.map((l) => ({
      batchId: l.batchId,
      quantityReceived: l.quantityReceived,
      shortageQuantity: l.shortageQuantity
    }))
  });
  await insertChangeLog(tx, {
    pharmacyId: ctx.pharmacyId,
    entity: "stock_transfer",
    entityId: transfer.id,
    op: "upsert",
    data: {
      id: transfer.id,
      status: "received",
      hasShortage,
      receivedAt: payload.receivedAt
    },
    createdAt: now
  });
}

// src/sync/appliers/shift.ts
import { eq as eq12, and as and12 } from "drizzle-orm";
async function verifyShiftCounterAndCashier(tx, ctx, counterId, cashierUserId, explicitBranchId) {
  if (ctx.counterId && counterId !== ctx.counterId) {
    throw new SyncRejectedError(
      "CROSS_TENANT_REFERENCE",
      `Device counterId (${ctx.counterId}) does not match shift counterId (${counterId})`
    );
  }
  const counterRows = await tx.select({ id: counters.id, branchId: counters.branchId }).from(counters).where(and12(eq12(counters.id, counterId), eq12(counters.pharmacyId, ctx.pharmacyId))).limit(1);
  const counter = counterRows[0];
  if (!counter) {
    const [crossCounter] = await tx.select({ id: counters.id }).from(counters).where(eq12(counters.id, counterId)).limit(1);
    if (crossCounter) {
      throw new SyncRejectedError(
        "CROSS_TENANT_REFERENCE",
        `Referenced counter ${counterId} belongs to another pharmacy tenant`
      );
    }
    throw new SyncRetryLaterError(
      "UNKNOWN_COUNTER",
      `Counter ${counterId} not found for pharmacy ${ctx.pharmacyId}`
    );
  }
  if (ctx.branchId && counter.branchId !== ctx.branchId) {
    throw new SyncRejectedError(
      "CROSS_TENANT_REFERENCE",
      `Device branchId (${ctx.branchId}) does not match counter branchId (${counter.branchId})`
    );
  }
  if (explicitBranchId && explicitBranchId !== counter.branchId) {
    throw new SyncRejectedError(
      "CROSS_TENANT_REFERENCE",
      `Shift branchId (${explicitBranchId}) does not match counter branchId (${counter.branchId})`
    );
  }
  await verifyTenantEntity(tx, users, cashierUserId, ctx.pharmacyId, "UNKNOWN_USER", "user");
  return counter.branchId;
}
