import { eq as eq15, and as and14, gt, asc as asc3, isNull as isNull2, or } from "drizzle-orm";
async function pullChangeLog(db, ctx, params) {
  const { cursor, limit, overlap = 0 } = params;
  const effectiveCursor = Math.max(0, cursor - overlap);
  const conditions = [eq15(changeLog.pharmacyId, ctx.pharmacyId), gt(changeLog.seq, effectiveCursor)];
  if (ctx.branchId) {
    conditions.push(or(isNull2(changeLog.branchId), eq15(changeLog.branchId, ctx.branchId)));
  }
  const rawRows = await db.select({
    seq: changeLog.seq,
    entity: changeLog.entity,
    entityId: changeLog.entityId,
    op: changeLog.op,
    data: changeLog.data,
    createdAt: changeLog.createdAt
  }).from(changeLog).where(and14(...conditions)).orderBy(asc3(changeLog.seq)).limit(limit + 1);
  const hasMore = rawRows.length > limit;
  const pageRows = hasMore ? rawRows.slice(0, limit) : rawRows;
  const changes = pageRows.map((r) => ({
    seq: Number(r.seq),
    entity: r.entity,
    entityId: r.entityId,
    op: r.op,
    data: r.data || {},
    createdAt: r.createdAt
  }));
  const nextCursor = pageRows.length > 0 ? Number(pageRows[pageRows.length - 1].seq) : cursor;
  return {
    changes,
    nextCursor,
    hasMore
  };
}

// src/routes/sync.ts
var syncRoutes = async (fastify) => {
  fastify.post(
    "/push",
    {
      preHandler: [requireDeviceAuth]
    },
    async (request, reply) => {
      const parseResult = SyncPushRequestSchema.safeParse(request.body);
      if (!parseResult.success) {
        return reply.status(400).send({
          statusCode: 400,
          error: "Bad Request",
          message: parseResult.error.issues[0]?.message || "Invalid sync push request payload"
        });
      }
      const db = request.server.db || getDb();
      const deviceCtx = request.deviceContext;
      const results = await processSyncPushEvents(
        db,
        {
          pharmacyId: deviceCtx.pharmacyId,
          branchId: deviceCtx.branchId,
          deviceId: deviceCtx.deviceId,
          counterId: deviceCtx.counterId
        },
        parseResult.data.events
      );
      return reply.status(200).send({ results });
    }
  );
  fastify.get(
    "/pull",
    {
      preHandler: [requireDeviceAuth]
    },
    async (request, reply) => {
      const parseResult = SyncPullQuerySchema.safeParse(request.query);
      if (!parseResult.success) {
        return reply.status(400).send({
          statusCode: 400,
          error: "Bad Request",
          message: parseResult.error.issues[0]?.message || "Invalid cursor or limit parameter"
        });
      }
      const db = request.server.db || getDb();
      const deviceCtx = request.deviceContext;
      const response = await pullChangeLog(
        db,
        {
          pharmacyId: deviceCtx.pharmacyId,
          branchId: deviceCtx.branchId
        },
        parseResult.data
      );
      return reply.status(200).send(response);
    }
  );
};

