    pharmacyId,
    from,
    to,
    ledgerSalesTotalPaisa,
    documentsSalesTotalPaisa,
    salesDifferencePaisa,
    ledgerNetSalesPaisa,
    documentsNetSalesPaisa,
    netSalesDifferencePaisa,
    ledgerInventoryValuePaisa,
    batchesInventoryValuePaisa,
    inventoryDifferencePaisa,
    isReconciled
