// src/services/notification-service.ts
import { eq as eq45, and as and44, sql as sql29, desc as desc19, lte as lte12, gte as gte12 } from "drizzle-orm";
async function getUserNotifications(db, pharmacyId, userId) {
  const rows = await db.select().from(userNotifications).where(and44(eq45(userNotifications.pharmacyId, pharmacyId), eq45(userNotifications.userId, userId))).orderBy(userNotifications.isRead, desc19(userNotifications.createdAt)).limit(50);
  const [countRow] = await db.select({
    unread: sql29`count(*) filter (where ${userNotifications.isRead} = false)`,
    total: sql29`count(*)`
  }).from(userNotifications).where(and44(eq45(userNotifications.pharmacyId, pharmacyId), eq45(userNotifications.userId, userId)));
  const unreadCount = Number(countRow?.unread ?? 0);
  const total = Number(countRow?.total ?? 0);
  return {
    items: rows.map((r) => ({
      id: r.id,
      pharmacyId: r.pharmacyId,
      userId: r.userId,
      type: r.type,
      title: r.title,
      message: r.message,
      severity: r.severity,
      entityType: r.entityType,
      entityId: r.entityId,
      link: r.link,
      isRead: r.isRead,
      readAt: r.readAt,
      createdAt: r.createdAt
    })),
    unreadCount,
    total
  };
}
async function markNotificationAsRead(db, pharmacyId, userId, notificationId) {
  const now = (/* @__PURE__ */ new Date()).toISOString();
  const res = await db.update(userNotifications).set({
    isRead: true,
    readAt: now
  }).where(
    and44(
      eq45(userNotifications.id, notificationId),
      eq45(userNotifications.pharmacyId, pharmacyId),
      eq45(userNotifications.userId, userId)
    )
  ).returning({ id: userNotifications.id });
  return res.length > 0;
}
async function markAllNotificationsAsRead(db, pharmacyId, userId) {
  const now = (/* @__PURE__ */ new Date()).toISOString();
  const res = await db.update(userNotifications).set({
    isRead: true,
    readAt: now
  }).where(
    and44(
      eq45(userNotifications.pharmacyId, pharmacyId),
      eq45(userNotifications.userId, userId),
      eq45(userNotifications.isRead, false)
    )
  ).returning({ id: userNotifications.id });
  return res.length;
}
async function refreshSystemNotifications(db, pharmacyId, userId, userRole) {
  const nowIso = (/* @__PURE__ */ new Date()).toISOString();
  const today = getKarachiBusinessDate(nowIso);
  const thirtyDaysAhead = getKarachiBusinessDate(new Date(Date.now() + 30 * 24 * 60 * 60 * 1e3));
  let newAlertsCount = 0;
  const canViewStock = !userRole || ["owner", "manager", "pharmacist"].includes(userRole);
  if (canViewStock) {
    const expiringBatches = await db.select({
      batchId: batches.id,
      batchNo: batches.batchNo,
      expiryDate: batches.expiryDate,
      productName: products.brandName,
      stock: sql29`COALESCE(SUM(${stockMovements.quantitySigned}), 0)`.mapWith(Number)
    }).from(batches).innerJoin(products, eq45(batches.productId, products.id)).innerJoin(
      stockMovements,
      and44(eq45(batches.id, stockMovements.batchId), eq45(stockMovements.pharmacyId, pharmacyId))
    ).where(
      and44(
        eq45(batches.pharmacyId, pharmacyId),
        gte12(batches.expiryDate, today),
        lte12(batches.expiryDate, thirtyDaysAhead)
      )
    ).groupBy(batches.id, batches.batchNo, batches.expiryDate, products.brandName).having(sql29`COALESCE(SUM(${stockMovements.quantitySigned}), 0) > 0`).limit(5);
    for (const b of expiringBatches) {
      const [existing] = await db.select({ id: userNotifications.id }).from(userNotifications).where(
        and44(
          eq45(userNotifications.pharmacyId, pharmacyId),
          eq45(userNotifications.userId, userId),
          eq45(userNotifications.entityId, b.batchId),
          eq45(userNotifications.type, "expiring_stock")
        )
      ).limit(1);
      if (!existing) {
        await db.insert(userNotifications).values({
          id: generateUuidV7(),
          pharmacyId,
          userId,
          type: "expiring_stock",
          title: `Expiring Batch: ${b.productName}`,
          message: `Batch ${b.batchNo} expires on ${b.expiryDate}. Please rotate or return.`,
          severity: "warning",
          entityType: "batch",
          entityId: b.batchId,
          link: "/batches-expiry",
          isRead: false,
          createdAt: nowIso
        });
        newAlertsCount++;
      }
    }
  }
  const canViewSync = !userRole || ["owner", "manager"].includes(userRole);
  if (canViewSync) {
    const exceptions = await db.select({ id: rejectedEvents.id, message: rejectedEvents.message }).from(rejectedEvents).where(eq45(rejectedEvents.pharmacyId, pharmacyId)).limit(3);
    for (const exc of exceptions) {
      const [existing] = await db.select({ id: userNotifications.id }).from(userNotifications).where(
        and44(
          eq45(userNotifications.pharmacyId, pharmacyId),
          eq45(userNotifications.userId, userId),
          eq45(userNotifications.entityId, exc.id),
          eq45(userNotifications.type, "sync_exceptions")
        )
      ).limit(1);
      if (!existing) {
        await db.insert(userNotifications).values({
          id: generateUuidV7(),
          pharmacyId,
          userId,
          type: "sync_exceptions",
          title: "Sync Conflict Detected",
          message: `Sync payload rejected: ${exc.message.slice(0, 100)}`,
          severity: "critical",
          entityType: "rejected_event",
          entityId: exc.id,
          link: "/admin-devices",
          isRead: false,
          createdAt: nowIso
        });
        newAlertsCount++;
      }
    }
  }
  const canViewPeriodClose = !userRole || ["owner", "accountant"].includes(userRole);
  if (canViewPeriodClose) {
    const openPeriods = await db.select({ id: fiscalPeriods.id, endDate: fiscalPeriods.endDate }).from(fiscalPeriods).where(
      and44(
        eq45(fiscalPeriods.pharmacyId, pharmacyId),
        eq45(fiscalPeriods.status, "open"),
        lte12(fiscalPeriods.endDate, today)
      )
    ).limit(1);
    if (openPeriods.length > 0 && openPeriods[0]) {
      const period = openPeriods[0];
      const [existing] = await db.select({ id: userNotifications.id }).from(userNotifications).where(
        and44(
          eq45(userNotifications.pharmacyId, pharmacyId),
          eq45(userNotifications.userId, userId),
          eq45(userNotifications.entityId, period.id),
          eq45(userNotifications.type, "period_close")
        )
      ).limit(1);
      if (!existing) {
        await db.insert(userNotifications).values({
          id: generateUuidV7(),
          pharmacyId,
          userId,
          type: "period_close",
          title: "Fiscal Period Close Due",
          message: `Fiscal period ended on ${period.endDate} is still open. Please complete period close checklist.`,
          severity: "info",
          entityType: "fiscal_period",
          entityId: period.id,
          link: "/finance-period-close",
          isRead: false,
          createdAt: nowIso
        });
        newAlertsCount++;
      }
    }
  }
  return newAlertsCount;
}

